package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {







    @Test
    public void testIsNumber_Decimals() {
        assertTrue(NumberUtils.isNumber("123.45"));
        assertTrue(NumberUtils.isNumber("-123.45"));
        assertTrue(NumberUtils.isNumber(".45")); // Note: Logic requires foundDigit, so "." is false, ".4" is true
        assertTrue(NumberUtils.isNumber("123."));
        assertFalse(NumberUtils.isNumber("."));
        assertFalse(NumberUtils.isNumber("12.34.56"));
        assertFalse(NumberUtils.isNumber("123.e10")); // Dec in exponent check
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {









    @Test
    public void testIsNumber_Exponents() {
        assertTrue(NumberUtils.isNumber("123e10"));
        assertTrue(NumberUtils.isNumber("123E10"));
        assertTrue(NumberUtils.isNumber("123e+10"));
        assertTrue(NumberUtils.isNumber("123e-10"));
        assertTrue(NumberUtils.isNumber("-123E10"));
        assertFalse(NumberUtils.isNumber("e10"));
        assertFalse(NumberUtils.isNumber("123e"));
        assertFalse(NumberUtils.isNumber("123e+-10"));
        assertFalse(NumberUtils.isNumber("123e10e10"));
        assertFalse(NumberUtils.isNumber("123e10.5"));
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        assertTrue(NumberUtils.isNumber("123.45f"));
        assertFalse(NumberUtils.isNumber("123.45df")); // Only one qualifier allowed at end

        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));
        assertFalse(NumberUtils.isNumber("123.45L")); // L not allowed with decimal
        assertFalse(NumberUtils.isNumber("123e10L")); // L not allowed with exponent
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {













    @Test
    public void testIsNumber_EdgeCases() {
        // Single digit with sign
        assertTrue(NumberUtils.isNumber("-1"));

        // Testing the "allowSigns && !foundDigit" branch in while loop
        // This handles cases where the loop might terminate early
        assertFalse(NumberUtils.isNumber("-"));
        assertFalse(NumberUtils.isNumber("1E-"));

        // Testing "foundDigit" requirement for decimal point
        assertFalse(NumberUtils.isNumber("."));
        assertTrue(NumberUtils.isNumber("1."));

        // Testing the specific combination of characters
        assertFalse(NumberUtils.isNumber("123.e10")); 

        // Testing characters that are not allowed
        assertFalse(NumberUtils.isNumber("123 "));
        assertFalse(NumberUtils.isNumber(" 123"));
    }


}

